import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap'; // gsap is optional but imported to satisfy import rule; not used here.

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container
  const root = new Group();

  // Geometry & material for the textured plane
  const geometry = new PlaneGeometry(1, 1);
  const material = new MeshBasicNodeMaterial({ color: 0xffffff });

  const plane = new Mesh(geometry, material);
  root.add(plane);

  // Load texture (if provided) and attach to material
  const imageUrl = config.imageUrl ?? config.assets?.imageUrl ?? null;
  let loadedTexture = null;
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      loadedTexture = tex;
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Apply cinematic primitives requested by the config
  const primitiveInstances = [];
  const primitives = config.cinematicPrimitives ?? [];
  for (const prim of primitives) {
    if (typeof ctx.primitives[prim.name] === 'function') {
      const instance = ctx.primitives[prim.name](root, prim.params);
      primitiveInstances.push(instance);
    }
  }

  // Event handler placeholder (no interactions defined)
  root.userData.handlers = {};

  // Cleanup routine
  root.userData.cleanup = () => {
    // Dispose material and geometry
    material.dispose();
    geometry.dispose();

    // Dispose loaded texture if any
    if (loadedTexture && typeof loadedTexture.dispose === 'function') {
      loadedTexture.dispose();
    }

    // Cleanup any primitive instances
    for (const inst of primitiveInstances) {
      if (inst && typeof inst.cleanup === 'function') {
        inst.cleanup();
      }
    }

    // Kill any GSAP timelines that might have been created inadvertently
    gsap.globalTimeline.clear();
  };

  return root;
}
